+
+const chromeCandidates = [
+  process.env.CHROME_PATH,
+  "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
+  "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
+  "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
+].filter(Boolean);
+const executablePath = chromeCandidates.find((candidate) => fs.existsSync(candidate));
+
+if (!executablePath) {
+  throw new Error("No Chrome/Edge executable found. Set CHROME_PATH to run the screenshot verification.");
+}
+
+fs.mkdirSync(SHOTS, { recursive: true });
+if (!SAVE) {
+  for (const viewport of VIEWPORTS) {
+    const deliverable = path.join(DELIVERABLES, `${viewport.name}.png`);
+    if (!fs.existsSync(deliverable) || fs.statSync(deliverable).size < 30_000) {
+      throw new Error(`Missing saved deliverable ${deliverable}. Run npm run screenshots:save first.`);
+    }
+  }
+}
+
+const report = {
+  generatedAt: new Date().toISOString(),
+  browser: executablePath,
+  viewports: [],
+  interactions: {},
+};
+
+function fail(message) {
+  throw new Error(message);
+}
+
+async function waitForReady(page) {
+  await page.waitForSelector('[data-testid="agent-card"]', { timeout: 20_000 });
+  await page.evaluate(async () => {
+    await document.fonts.ready;
+  });
+  await page.waitForTimeout(1400);
+}
+
+async function inspectViewport(page, viewport) {
+  return page.evaluate((expectedColumns) => {
+    const cards = Array.from(document.querySelectorAll('[data-testid="agent-card"]'));
+    const grid = document.querySelector(".agent-grid");
+    const room = document.querySelector('[data-testid="pixel-room"]');
+    const roomSvg = room ? room.querySelector(".room-svg") : null;
+    const roomBox = roomSvg ? roomSvg.getBoundingClientRect() : null;
+    const equityLine = document.querySelector(".equity-line--core");
+    const clientWidth = document.documentElement.clientWidth;
+    const overflowing = Array.from(document.querySelectorAll("body *"))
+      .filter((element) => {
+        const style = getComputedStyle(element);
+        if (style.display === "none" || style.visibility === "hidden" || style.position === "fixed") return false;
+        if (element.closest(".room-viewport") || element.closest("svg")) return false;
+        const rect = element.getBoundingClientRect();
+        return rect.width > 0 && (rect.right > clientWidth + 1 || rect.left < -1);
+      })
+      .slice(0, 8)
+      .map((element) => `${element.tagName.toLowerCase()}.${String(element.className).split(" ").slice(0, 2).join(".")}`);
+
+    return {
+      cards: cards.length,
+      agents: cards.map((card) => card.getAttribute("data-agent")),
+      columns: grid ? getComputedStyle(grid).gridTemplateColumns.split(" ").filter(Boolean).length : 0,
+      expectedColumns,
+      roomWidth: roomBox ? Math.round(roomBox.width) : 0,
+      roomHeight: roomBox ? Math.round(roomBox.height) : 0,
+      candleBodies: document.querySelectorAll(".candle-body").length,
+      stations: document.querySelectorAll(".station").length,
+      thresholds: document.querySelectorAll(".threshold-list li").length,
+      hasEquityPath: Boolean(equityLine && (equityLine.getAttribute("d") || "").length > 100),
+      scrollWidth: document.documentElement.scrollWidth,
+      bodyScrollWidth: document.body.scrollWidth,
+      clientWidth,
+      innerWidth: window.innerWidth,
+      overflowing,
+      title: document.title,
+      h1: document.querySelector(".brand-copy h1")?.textContent?.replace(/\s+/g, " ").trim() ?? "",
+    };
+  }, viewport.columns);
+}
