+  }
+  if (metrics.roomWidth < 300 || metrics.roomHeight < 180) {
+    fail(`Pixel room is too small at ${viewport.width}px (${metrics.roomWidth}x${metrics.roomHeight})`);
+  }
+  if (metrics.candleBodies < 20) fail(`Candle chart did not render at ${viewport.width}px`);
+  if (metrics.stations < 6) fail(`Pixel room stations missing at ${viewport.width}px`);
+  if (metrics.thresholds !== 8) fail(`Threshold table incomplete at ${viewport.width}px`);
+  if (!metrics.hasEquityPath) fail(`Equity chart path missing at ${viewport.width}px`);
+  if (metrics.scrollWidth > metrics.clientWidth + 1 || metrics.bodyScrollWidth > metrics.clientWidth + 1) {
