+import type { Candle } from "../data/types";
+
+interface CandleChartProps {
+  candles: Candle[];
+}
+
+const W = 640;
+const H = 280;
+const PLOT = { left: 8, right: 570, top: 16, bottom: 206 };
+const VOLUME_TOP = 222;
+const VOLUME_BOTTOM = 258;
+
+export function CandleChart({ candles }: CandleChartProps) {
+  const data = candles.slice(-30);
+  if (data.length === 0) {
+    return <div className="chart-empty">WAITING FOR TAPE</div>;
+  }
+  const min = Math.min(...data.map((candle) => candle.low));
+  const max = Math.max(...data.map((candle) => candle.high));
+  const pad = (max - min || 1) * 0.12;
+  const lo = min - pad;
+  const hi = max + pad;
+  const range = hi - lo || 1;
+  const plotW = PLOT.right - PLOT.left;
+  const plotH = PLOT.bottom - PLOT.top;
+  const slot = plotW / data.length;
+  const bodyW = Math.max(3, Math.min(10, slot * 0.58));
+  const yFor = (value: number): number => PLOT.top + (1 - (value - lo) / range) * plotH;
+  const maxVolume = Math.max(...data.map((candle) => candle.volume), 1);
+
+  const averageWindow = 7;
+  const averages = data.map((_, index) => {
+    const start = Math.max(0, index - averageWindow + 1);
+    const slice = data.slice(start, index + 1);
+    return slice.reduce((sum, candle) => sum + candle.close, 0) / slice.length;
+  });
+  const averageLine = averages
+    .map((value, index) => `${index === 0 ? "M" : "L"}${(PLOT.left + slot * (index + 0.5)).toFixed(2)},${yFor(value).toFixed(2)}`)
+    .join(" ");
+
+  const last = data[data.length - 1];
+  const lastY = yFor(last.close);
+
+  return (
+    <svg
+      className="candle-chart"
+      viewBox={`0 0 ${W} ${H}`}
+      preserveAspectRatio="none"
+      role="img"
+      aria-label={`Candlestick chart with ${data.length} candles, latest close ${last.close.toFixed(5)}`}
+      data-testid="candle-chart"
+    >
+      {[0, 0.25, 0.5, 0.75, 1].map((tick) => {
+        const y = PLOT.top + plotH * tick;
+        const value = hi - range * tick;
+        return (
+          <g key={`c-grid-${tick}`}>
+            <line x1={PLOT.left} x2={PLOT.right} y1={y} y2={y} className="chart-grid" />
+            <text x={W - 4} y={y + 3} textAnchor="end" className="chart-axis-label">
+              {value.toFixed(5)}
+            </text>
+          </g>
+        );
+      })}
+
+      {data.map((candle, index) => {
+        const x = PLOT.left + slot * (index + 0.5);
+        const openY = yFor(candle.open);
+        const closeY = yFor(candle.close);
+        const top = Math.min(openY, closeY);
+        const height = Math.max(2, Math.abs(closeY - openY));
+        const rising = candle.close >= candle.open;
+        const volumeH = (candle.volume / maxVolume) * (VOLUME_BOTTOM - VOLUME_TOP);
+        return (
+          <g key={`candle-${candle.t}`}>
+            <line
+              x1={x}
+              x2={x}
+              y1={yFor(candle.high)}
+              y2={yFor(candle.low)}
+              className={rising ? "wick wick-up" : "wick wick-down"}
+            />
+            <rect
+              x={x - bodyW / 2}
+              y={top}
+              width={bodyW}
+              height={height}
+              className={rising ? "candle-body candle-up" : "candle-body candle-down"}
+            />
+            <rect
+              x={x - bodyW / 2}
+              y={VOLUME_BOTTOM - volumeH}
+              width={bodyW}
+              height={Math.max(1, volumeH)}
+              className={rising ? "candle-volume candle-volume--up" : "candle-volume candle-volume--down"}
+            />
+          </g>
+        );
+      })}
+
+      <path d={averageLine} className="average-line" />
+      <line x1={PLOT.left} x2={PLOT.right} y1={lastY} y2={lastY} className="last-price-line" />
+      <rect x={PLOT.right + 4} y={lastY - 8} width={64} height={16} rx="2" className="last-price-tag" />
+      <text x={PLOT.right + 8} y={lastY + 4} className="last-price-text">
+        {last.close.toFixed(5)}
+      </text>
+      <text x={PLOT.left} y={H - 2} className="chart-axis-label">JEV // {data.length} CANDLES</text>
+      <text x={PLOT.right} y={H - 2} textAnchor="end" className="chart-axis-label">MA(7) / VOLUME</text>
+    </svg>
+  );
+}
