+@keyframes ping {
+  0% {
+    opacity: 0.22;
+    transform: scale(0.7);
+  }
+  55% {
+    opacity: 0.75;
+    transform: scale(1.2);
+  }
+  100% {
+    opacity: 0;
+    transform: scale(1.7);
+  }
+}
+
+@keyframes pnl-pulse {
+  0% {
+    opacity: 0.6;
+    transform: scale(0.8);
+    transform-origin: center;
+  }
+  100% {
+    opacity: 0;
+    transform: scale(2);
+    transform-origin: center;
+  }
+}
